export type AppLanguage = keyof typeof translations;
export type TranslationKey = keyof typeof translations.en;

interface AppLanguageContextValue {
  appLanguage: AppLanguage;
  setAppLanguage: (language: AppLanguage) => void;
  t: (key: TranslationKey) => string;
}

const AppLanguageContext = createContext<AppLanguageContextValue | null>(null);
const STORAGE_KEY = "meetily.appLanguage";

export function AppLanguageProvider({ children }: { children: ReactNode }) {
  // Keep the server and the first client render identical. Chinese is the product default;
  // a previously saved English choice is restored immediately after hydration.
  const [appLanguage, setAppLanguage] = useState<AppLanguage>("zh-CN");
  const [isInitialized, setIsInitialized] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === "en" || saved === "zh-CN") {
      setAppLanguage(saved);
    }
    setIsInitialized(true);
  }, []);

  useEffect(() => {
    if (!isInitialized) return;
    localStorage.setItem(STORAGE_KEY, appLanguage);
    document.documentElement.lang = appLanguage;
  }, [appLanguage, isInitialized]);

  const value = useMemo<AppLanguageContextValue>(() => ({
    appLanguage,
    setAppLanguage,
    t: (key) => translations[appLanguage][key],
  }), [appLanguage]);

  return <AppLanguageContext.Provider value={value}>{children}</AppLanguageContext.Provider>;
}

export function useAppLanguage(): AppLanguageContextValue {
  const context = useContext(AppLanguageContext);
  if (!context) throw new Error("useAppLanguage must be used inside AppLanguageProvider");
  return context;
}
